-- =============================================================================
-- RAG leve de legislação — Corpus Curado (Batch 8)
-- Ampliação das Matérias Jurídicas com Cobertura Inicial:
-- - Legislação Institucional (48): PF (482), PRF (483), PM/CBM (484), Migração (489),
--   Químicos (490), ICMBio (558)
-- - Proteção a Grupos Vulneráveis (61): Atendimento Prioritário (476), Acessibilidade (477),
--   Cão-Guia (479), Crimes contra a Pessoa Idosa (480), Igualdade Racial (481)
-- - Direito Processual Civil (33): Normas Fundamentais (523), Competência (251),
--   Estabilização da Tutela (525), Recursos e ACP (528/529)
-- - Direito Previdenciário (35): Benefícios RGPS (261), Crimes Previdenciários (262),
--   RPPS Servidores (554)
--
-- Fontes Oficiais: Presidência da República (Planalto) e Constituição Federal.
-- Dispositivos vigentes e atualizados. Sem artigos revogados. Idempotente.
-- =============================================================================

insert into public.legislacao_artigos (referencia, texto, vigencia_de, id_materia, id_topico) values

-- -----------------------------------------------------------------------------
-- LEGISLAÇÃO INSTITUCIONAL E NORMAS ESPECÍFICAS (ID 48)
-- -----------------------------------------------------------------------------
('Lei nº 10.446/2002 — art. 1º', 'Na forma do inciso I do § 1º do art. 144 da Constituição, quando houver repercussão interestadual ou internacional que exija repressão uniforme, poderá o Departamento de Polícia Federal do Ministério da Justiça, sem prejuízo da responsabilidade dos órgãos de segurança pública arrolados no art. 144 da Constituição Federal, em especial das Polícias Militares e Civis dos Estados, proceder à investigação, dentre outras, das seguintes infrações penais: sequestro, cárcere privado e extorsão mediante sequestro; furto, roubo ou receptação de cargas; crimes cibernéticos; e infrações contra direitos humanos.', '2002-05-08', 48, 482),
('Lei nº 9.654/1998 — art. 1º e 2º', 'É criada a carreira de Policial Rodoviário Federal. São atribuições do cargo de Policial Rodoviário Federal as atividades de natureza policial voltadas à fiscalização, ao patrulhamento ostensivo e ao policiamento das rodovias federais, à garantia da segurança pública e à preservação da ordem pública e da incolumidade das pessoas e do patrimônio da União.', '1998-06-02', 48, 483),
('Lei nº 14.751/2023 — art. 1º e 5º (LONPMM)', 'Esta Lei institui a Lei Orgânica Nacional das Polícias Militares e dos Corpos de Bombeiros Militares dos Estados, do Distrito Federal e dos Territórios. Compete privativamente às Polícias Militares a polícia ostensiva e a preservação da ordem pública; e aos Corpos de Bombeiros Militares a coordenação e a execução de ações de defesa civil, prevenção e combate a incêndios e busca e salvamento.', '2023-12-12', 48, 484),
('Lei nº 13.445/2017 — art. 3º e 45 (Lei de Migração)', 'A política migratória brasileira rege-se pelos princípios: universalidade, indivisibilidade e interdependência dos direitos humanos; acolhimento humanitário; não criminalização da migração; não discriminação; e não repulsão (non-refoulement). São medidas de retirada compulsória do território nacional: repatriação, deportação e expulsão. Não se procederá à deportação ou à expulsão de nenhum indivíduo para país onde sua vida ou sua integridade pessoal esteja em risco.', '2017-05-24', 48, 489),
('Lei nº 10.357/2001 — art. 1º', 'Estão sujeitos a controle e fiscalização pelo Departamento de Polícia Federal os produtos químicos suscetíveis de utilização como insumos na elaboração ilícita de substâncias entorpecentes, psicotrópicas ou que determinem dependência física ou psíquica.', '2001-12-27', 48, 490),
('Lei nº 11.516/2007 — art. 1º (ICMBio)', 'É criado o Instituto Chico Mendes de Conservação da Biodiversidade - Instituto Chico Mendes (ICMBio), autarquia federal dotada de autonomia administrativa e financeira, vinculada ao Ministério do Meio Ambiente, com a finalidade de: executar as ações do Sistema Nacional de Unidades de Conservação da Natureza (SNUC), propondo, implantando, gerindo, protegendo, fiscalizando e monitorando as unidades de conservação instituídas pela União; e exercer o poder de polícia ambiental.', '2007-08-28', 48, 558),

-- -----------------------------------------------------------------------------
-- LEGISLAÇÃO DE PROTEÇÃO A GRUPOS VULNERÁVEIS (ID 61)
-- -----------------------------------------------------------------------------
('Lei nº 10.048/2000 — art. 1º (Atendimento Prioritário)', 'As pessoas com deficiência, os idosos com idade igual ou superior a 60 (sessenta) anos, as gestantes, as lactantes, as pessoas com crianças de colo, os obesos e as pessoas com transtorno do espectro autista terão atendimento prioritário nos termos desta Lei. (Redação atualizada pela Lei nº 14.626, de 2023)', '2000-11-08', 61, 476),
('Lei nº 10.098/2000 — art. 2º (Acessibilidade)', 'Para os fins desta Lei são estabelecidas as seguintes definições: acessibilidade: possibilidade e condição de alcance para utilização, com segurança e autonomia, de espaços, mobiliários, vias e transportes por pessoa com deficiência ou com mobilidade reduzida; barreiras: qualquer entrave, obstáculo, atitude ou comportamento que limite ou impeça a participação social da pessoa; desenho universal: concepção de produtos e ambientes a serem usados por todas as pessoas, sem necessidade de adaptação.', '2000-12-19', 61, 477),
('Lei nº 11.126/2005 — art. 1º (Cão-Guia)', 'É assegurado a qualquer pessoa com deficiência visual acompanhada de cão-guia o direito de ingressar e de permanecer com o animal em todos os meios de transporte e em estabelecimentos abertos ao público, de uso público e privados de uso coletivo, desde que observadas as condições sanitárias.', '2005-06-27', 61, 479),
('Lei nº 10.741/2003 — art. 98, 102 e 104 (Crimes contra a Pessoa Idosa)', 'Abandonar a pessoa idosa em hospitais, casas de saúde ou não prover suas necessidades básicas: Pena - detenção, de 6 meses a 3 anos. Apropriar-se de ou desviar bens, proventos ou pensão de pessoa idosa: Pena - reclusão de 1 a 4 anos. Reter o cartão magnético de conta bancária de pessoa idosa para assegurar pagamento de dívida: Pena - detenção de 6 meses a 2 anos e multa. (Redação da Lei nº 14.423/2022)', '2003-10-01', 61, 480),
('Lei nº 12.288/2010 — art. 31 e 39 (Igualdade Racial)', 'Aos remanescentes das comunidades dos quilombos que estejam ocupando suas terras é reconhecida a propriedade definitiva, devendo o Estado emitir-lhes os títulos respectivos. O poder público promoverá ações que assegurem a igualdade de oportunidades no mercado de trabalho para a população negra, inclusive mediante a implementação de incentivos e ações afirmativas.', '2010-07-20', 61, 481),

-- -----------------------------------------------------------------------------
-- DIREITO PROCESSUAL CIVIL (ID 33)
-- -----------------------------------------------------------------------------
('CPC/2015 — art. 5º, 6º, 9º e 10 (Normas Fundamentais)', 'Aquele que de qualquer forma participa do processo deve comportar-se de acordo com a boa-fé. Todos os sujeitos do processo devem cooperar entre si para que se obtenha, em tempo razoável, decisão de mérito justa e efetiva. Não se proferirá decisão contra uma das partes sem que ela seja previamente ouvida. O juiz não pode decidir, em grau algum de jurisdição, com base em fundamento a respeito do qual não se tenha dado às partes oportunidade de se manifestar (vedação da decisão surpresa).', '2015-03-16', 33, 523),
('CPC/2015 — art. 46 e 64 (Competência)', 'A ação fundada em direito pessoal ou em direito real sobre bens móveis será proposta, em regra, no foro de domicílio do réu. A incompetência, absoluta ou relativa, será alegada como questão preliminar de contestação. A incompetência absoluta deve ser declarada de ofício e pode ser alegada em qualquer tempo e grau de jurisdição, mas a relativa prorroga-se se não alegada no momento oportuno.', '2015-03-16', 33, 251),
('CPC/2015 — art. 303 e 304 (Estabilização da Tutela Antecipada)', 'Nos casos em que a urgência for contemporânea à propositura da ação, a petição inicial pode limitar-se ao requerimento da tutela antecipada. A tutela antecipada concedida nos termos do art. 303 torna-se estável se da decisão que a conceder não for interposto o respectivo agravo de instrumento, caso em que o processo será extinto.', '2015-03-16', 33, 525),
('CPC/2015 — art. 98 (Gratuidade de Justiça)', 'A pessoa natural ou jurídica, brasileira ou estrangeira, com insuficiência de recursos para pagar as custas, as despesas processuais e os honorários advocatícios tem direito à gratuidade da justiça, na forma da lei. A concessão de gratuidade da justiça não afasta a responsabilidade do beneficiário pelas despesas processuais e pelos honorários advocatícios decorrentes de sua sucumbência (exigibilidade suspensa por 5 anos).', '2015-03-16', 33, 355),
('CPC/2015 — art. 1.009, 1.015 e 1.022 (Recursos Cíveis)', 'Da sentença cabe apelação. Cabe agravo de instrumento contra as decisões interlocutórias que versarem sobre: tutelas provisórias; mérito do processo; rejeição da alegação de convenção de arbitragem; e redistribuição do ônus da prova. Cabem embargos de declaração contra qualquer decisão judicial para esclarecer obscuridade, eliminar contradição, suprir omissão ou corrigir erro material.', '2015-03-16', 33, 528),
('Lei nº 7.347/1985 — art. 1º e 5º (Ação Civil Pública)', 'Regem-se pelas disposições desta Lei as ações de responsabilidade por danos morais e patrimoniais causados ao meio ambiente, ao consumidor, a bens e direitos de valor artístico e histórico, à ordem econômica e à ordem urbanística. Têm legitimidade para propor a ação principal: o Ministério Público; a Defensoria Pública; a União, os Estados, o Distrito Federal e os Municípios; as autarquias, empresas públicas e fundações; e a associação legalmente constituída há pelo menos 1 ano.', '1985-07-24', 33, 529),

-- -----------------------------------------------------------------------------
-- DIREITO PREVIDENCIÁRIO (ID 35)
-- -----------------------------------------------------------------------------
('Lei nº 8.213/1991 — art. 42 e 59 (Incapacidade RGPS)', 'A aposentadoria por incapacidade permanente, uma vez cumprida, quando for o caso, a carência exigida, será devida ao segurado que, estando ou não em gozo de auxílio por incapacidade temporária, for considerado incapaz e insuscetível de reabilitação para o exercício de atividade que lhe garanta a subsistência. O auxílio por incapacidade temporária será devido ao segurado que ficar incapacitado para o seu trabalho habitual por mais de 15 dias consecutivos. (Redação da EC nº 103/2019 e Lei nº 13.846/2019)', '1991-07-24', 35, 261),
('Lei nº 8.213/1991 — art. 74 e 86 (Pensão por Morte e Auxílio-Acidente)', 'A pensão por morte será devida ao conjunto dos dependentes do segurado que falecer, aposentado ou não, a contar da data do óbito, quando requerida em até 180 dias para os filhos menores de 16 anos, ou em até 90 dias para os demais. O auxílio-acidente será concedido, como indenização, ao segurado quando, após consolidação das lesões decorrentes de acidente de qualquer natureza, resultarem sequelas que impliquem redução da capacidade para o trabalho habitual.', '1991-07-24', 35, 261),
('Código Penal — art. 168-A (Apropriação Indébita Previdenciária)', 'Deixar de repassar à previdência social as contribuições recolhidas dos contribuintes, no prazo e forma legal ou convencional: Pena - reclusão, de 2 (dois) a 5 (cinco) anos, e multa. § 2º É extinta a punibilidade se o agente, espontaneamente, declara, confessa e efetua o pagamento das contribuições, importâncias ou valores e presta as informações devidas à previdência social antes do início do procedimento fiscal.', '2000-10-19', 35, 262),
('Código Penal — art. 337-A (Sonegação de Contribuição Previdenciária)', 'Suprimir ou reduzir contribuição social previdenciária e qualquer acessório, mediante as seguintes condutas: I - omitir de folha de pagamento da empresa ou de documento de informações previsto pela legislação previdenciária segurados empregados; II - deixar de lançar mensalmente nos títulos próprios da contabilidade as quantias descontadas; III - omitir receitas ou lucros auferidos: Pena - reclusão, de 2 a 5 anos, e multa.', '2000-10-19', 35, 262),
('CF/88 — art. 40 (RPPS - Servidores Públicos)', 'O regime próprio de previdência social dos servidores titulares de cargos efetivos terá caráter contributivo e solidário, mediante contribuição do respectivo ente federativo, de servidores ativos, de aposentados e de pensionistas, observados critérios que preservem o equilíbrio financeiro e atuarial. É vedada a instituição de novos regimes próprios de previdência social; e é vedada a concessão de aposentadoria com adoção de requisitos e critérios diferenciados, salvo servidores com deficiência ou que exerçam atividades com risco de morte ou sob condições especiais. (Redação dada pela EC nº 103/2019)', '1988-10-05', 35, 554)

on conflict (referencia) do update set 
    texto = excluded.texto, 
    vigencia_de = excluded.vigencia_de, 
    id_materia = excluded.id_materia, 
    id_topico = excluded.id_topico;
